<template>
    <div v-if="appNameExists" class="header">
        <img
             :src="appNameLogo[appName]"
             class="header__logo"
             @click="logoClickHandler"
        />
    </div>
</template>

<script>
import Connector from "../../core/Connector";

export default {
    name: "AccordionHeader",
    methods: {
        logoClickHandler() {
            Connector.click('addon_logo')
        }
    },
    props:['appName'],
    computed: {
      appNameExists() {
        return Object.keys(this.appNameLogo).includes(this.appName);
      },
      appNameLogo() {
        return {
          SABY: 'data:image/svg+xml;base64,',
          SETTY: 'data:image/svg+xml;base64,'
        }
      }
    }
}
</script>

<style>
.header {
    height: 30px;
    margin-bottom: 6px;
    pointer-events: none;
}
.header__logo {
    height: 28px;
    width: 84px;
    margin-left: 11px;
}
</style>
